16	def d3_canvas_css() -> str:
17	    return dedent(
18	        """
19	        :root {
20	          --warp-bg: #121212;
21	          --warp-panel: #1e1e1d;
22	          --warp-panel-2: #292929;
23	          --warp-border: #404040;
24	          --warp-text: #faf9f6;
25	          --warp-muted: #b4b4b2;
26	          --warp-dim: #868584;
27	          --warp-accent: #a43787;
28	          --warp-green: #34895c;
29	          --warp-blue: #2e5d9e;
30	          --warp-purple: #754dac;
31	          --warp-yellow: #c0872a;
32	          --warp-font-sans: 'Matter', 'DM Sans', system-ui, sans-serif;
33	          --warp-font-mono: 'Matter Mono', 'Roboto Mono', ui-monospace, monospace;
34	        }
35	        * { box-sizing: border-box; }
36	        body { margin: 0; min-height: 100vh; background: var(--warp-bg); color: var(--warp-text); font-family: var(--warp-font-sans); }
37	        a { color: var(--warp-text); text-decoration-color: var(--warp-accent); text-underline-offset: 3px; }
