91	def d3_canvas_runtime_script() -> str:
92	    return dedent(
93	        f"""
94	        <script>
95	        (() => {{
96	          const D3_CDN_URL = {D3_CDN_URL!r};
97	          let attemptedLoad = false;
98	          let activeGraphId = null;
99	          let selectedNodeId = null;
100	          let tourIndex = 0;
101	          const REQUIRED_GRAPH_IDS = ['system-overview', 'data-flow', 'code-dependency', 'user-action'];
102	          const DEFAULT_NODE_WIDTH = 220;
103	          const DEFAULT_NODE_HEIGHT = 116;
104	          const OVERVIEW_NODE_WIDTH = 360;
105	          const OVERVIEW_NODE_HEIGHT = 220;
106	          let zoomBehavior = null;
107	          let svgSelection = null;
108	          let viewportSelection = null;
109	          let currentData = null;
110	
111	          function setError(error) {{
112	            console.warn('D3 canvas render unavailable.', error || 'unknown error');
113	            document.body.classList.add('d3-canvas-error');
114	            const errorNode = document.querySelector('.d3-canvas-error');
115	            if (errorNode) errorNode.textContent = `D3 canvas failed to render: ${{error?.message || error || 'unknown error'}}`;
116	          }}
117	
118	          function readInlineData() {{
119	            if (window.PR_WALKTHROUGH_D3_DATA) return window.PR_WALKTHROUGH_D3_DATA;
120	            const script = document.getElementById('pr-walkthrough-data');
121	            if (!script) throw new Error('Missing pr-walkthrough-data script tag');
122	            return JSON.parse(script.textContent || '{{}}');
123	          }}
124	
125	          function activeGraph() {{
126	            return (currentData.graphs || []).find((graph) => graph.id === activeGraphId) || (currentData.graphs || [])[0];
127	          }}
128	
129	          function nodeMap(graph) {{ return new Map((graph.nodes || []).map((node) => [node.id, node])); }}
130	          function escapeHtml(value) {{
131	            return String(value ?? '').replace(/[&<>"']/g, (char) => ({{ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }}[char]));
132	          }}
133	          function listItems(items, render) {{
134	            if (!items || items.length === 0) return '<p class="d3-empty">None attached.</p>';
135	            return `<ul class="d3-detail-list">${{items.map(render).join('')}}</ul>`;
136	          }}
137	
138	          function renderTour(graph) {{
139	            const step = (graph.tour || [])[tourIndex];
140	            const label = document.querySelector('.d3-tour-step-label');
141	            const title = document.querySelector('.d3-tour-title');
142	            const body = document.querySelector('.d3-tour-body');
143	            const card = document.querySelector('.d3-tour-card');
144	            if (card) card.dataset.tourIndex = String(tourIndex);
145	            if (label) label.textContent = `Step ${{Math.min(tourIndex + 1, (graph.tour || []).length)}} / ${{(graph.tour || []).length || 0}}`;
146	            if (title) title.textContent = step?.title || graph.label || 'View tour';
147	            if (body) body.textContent = step?.body || graph.summary || '';
148	          }}
149	
150	          function renderDetails(node, graph) {{
151	            const panel = document.getElementById('pr-walkthrough-details');
152	            if (!panel) return;
153	            const step = (graph.tour || [])[tourIndex];
154	            if (!node) {{
155	              panel.innerHTML = '<p class="d3-panel-title">Selected point</p><p class="d3-empty">Select a node or use the tour controls.</p>';
156	              return;
157	            }}
158	            const details = Array.isArray(node.details) ? node.details : [];
159	            const files = Array.isArray(node.files) ? node.files : [];
160	            const comments = Array.isArray(node.comments) ? node.comments : [];
161	            const links = Array.isArray(node.links) ? node.links : [];
162	            panel.innerHTML = `
163	              <span class="d3-detail-kind">${{escapeHtml(graph.label)}} · ${{escapeHtml(node.kind || 'point of interest')}}</span>
164	              <h2 class="d3-detail-title">${{escapeHtml(node.title)}}</h2>
165	              <p class="d3-detail-summary">${{escapeHtml(node.summary || '')}}</p>
166	              ${{step?.nodeId === node.id ? `<section class="d3-detail-section"><h3>Tour context</h3><ul class="d3-detail-list"><li>${{escapeHtml(step.body || '')}}</li></ul></section>` : ''}}
167	              <section class="d3-detail-section"><h3>Explanation</h3>${{details.length ? `<ul class="d3-detail-list">${{details.map((item) => `<li>${{escapeHtml(item)}}</li>`).join('')}}</ul>` : '<p class="d3-empty">No additional detail provided.</p>'}}</section>
168	              <section class="d3-detail-section"><h3>Changed files</h3>${{listItems(files, (file) => `<li><a class="d3-file-link" href="${{escapeHtml(file.url || '#')}}" target="_blank" rel="noreferrer">${{escapeHtml(file.path || file.label || 'file')}}</a>${{file.note ? `<p>${{escapeHtml(file.note)}}</p>` : ''}}</li>`)}}</section>
169	              <section class="d3-detail-section"><h3>Existing review discussion</h3>${{listItems(comments, (comment) => `<li><span class="d3-comment-author">${{escapeHtml(comment.author || 'reviewer')}}</span>${{escapeHtml(comment.body || '')}}${{comment.url ? `<br><a href="${{escapeHtml(comment.url)}}" target="_blank" rel="noreferrer">Open comment</a>` : ''}}</li>`)}}</section>
170	              <section class="d3-detail-section"><h3>Links</h3>${{listItems(links, (link) => `<li><a href="${{escapeHtml(link.url || '#')}}" target="_blank" rel="noreferrer">${{escapeHtml(link.label || link.url || 'link')}}</a></li>`)}}</section>
171	            `;
172	          }}
173	
174	          function wrapText(selection, width, maxLines = 3) {{
175	            selection.each(function wrapEach() {{
176	              const text = window.d3.select(this);
177	              const datum = text.datum();
178	              const resolvedWidth = typeof width === 'function' ? Number(width(datum)) : Number(width);
179	              const resolvedMaxLines = typeof maxLines === 'function' ? Number(maxLines(datum)) : Number(maxLines);
180	              const words = text.text().split(new RegExp('\\\\s+')).filter(Boolean);
181	              const lineHeight = 15;
182	              const y = Number(text.attr('y') || 0);
183	              text.text('');
184	              let line = [];
185	              let lineNumber = 0;
186	              let tspan = text.append('tspan').attr('x', text.attr('x')).attr('y', y);
187	              for (const word of words) {{
188	                line.push(word);
189	                tspan.text(line.join(' '));
190	                if (tspan.node().getComputedTextLength() > resolvedWidth && line.length > 1) {{
191	                  line.pop();
192	                  tspan.text(line.join(' '));
193	                  line = [word];
194	                  lineNumber += 1;
195	                  if (lineNumber >= resolvedMaxLines) {{ tspan.text(`${{tspan.text()}}…`); break; }}
196	                  tspan = text.append('tspan').attr('x', text.attr('x')).attr('y', y + lineNumber * lineHeight).text(word);
197	                }}
198	              }}
199	            }});
200	          }}
201	          function nodeWidth(node, graph) {{
202	            return Number(node.width || (graph?.id === 'system-overview' ? OVERVIEW_NODE_WIDTH : DEFAULT_NODE_WIDTH));
203	          }}
204	          function nodeHeight(node, graph) {{
205	            return Number(node.height || (graph?.id === 'system-overview' ? OVERVIEW_NODE_HEIGHT : DEFAULT_NODE_HEIGHT));
206	          }}
207	          function nodeBoundaryPoint(from, to, padding, graph) {{
208	            const dx = to.x - from.x;
209	            const dy = to.y - from.y;
210	            if (dx === 0 && dy === 0) return {{ x: from.x, y: from.y }};
211	            const scale = 1 / Math.max(Math.abs(dx) / (nodeWidth(from, graph) / 2 + padding), Math.abs(dy) / (nodeHeight(from, graph) / 2 + padding));
212	            return {{ x: from.x + dx * scale, y: from.y + dy * scale }};
213	          }}
214	          function pathForEdge(edge, nodes, graph) {{
215	            const source = nodes.get(edge.source);
216	            const target = nodes.get(edge.target);
217	            if (!source || !target) return '';
218	            const start = nodeBoundaryPoint(source, target, 10, graph);
219	            const end = nodeBoundaryPoint(target, source, 18, graph);
220	            const dx = end.x - start.x;
221	            const control = Math.max(80, Math.abs(dx) * 0.42);
222	            return `M ${{start.x}} ${{start.y}} C ${{start.x + control}} ${{start.y}}, ${{end.x - control}} ${{end.y}}, ${{end.x}} ${{end.y}}`;
223	          }}
224	
225	          function applyFilters(graph) {{
226	            const query = (document.querySelector('.d3-search')?.value || '').trim().toLowerCase();
227	            const tourNodeId = (graph.tour || [])[tourIndex]?.nodeId;
228	            const matches = (node) => {{
229	              if (!query) return true;
230	              const haystack = [node.title, node.kind, node.summary, ...(node.details || []), ...(node.files || []).map((file) => file.path || file.label || ''), ...(node.comments || []).map((comment) => `${{comment.author || ''}} ${{comment.body || ''}}`)].join(' ').toLowerCase();
231	              return haystack.includes(query);
232	            }};
233	            const visible = new Set((graph.nodes || []).filter(matches).map((node) => node.id));
234	            window.d3.selectAll('.d3-node')
235	              .classed('is-dimmed', (node) => !visible.has(node.id))
236	              .classed('is-selected', (node) => node.id === selectedNodeId)
237	              .classed('is-tour-node', (node) => node.id === tourNodeId);
238	            window.d3.selectAll('.d3-edge').classed('is-dimmed', (edge) => !visible.has(edge.source) || !visible.has(edge.target));
239	          }}
240	
241	          function fitToView() {{
242	            if (!svgSelection || !viewportSelection || !zoomBehavior) return;
243	            const svg = svgSelection.node();
244	            const bounds = viewportSelection.node().getBBox();
245	            const fullWidth = svg.clientWidth || 1000;
246	            const fullHeight = svg.clientHeight || 700;
247	            const width = Math.max(bounds.width, 1);
248	            const height = Math.max(bounds.height, 1);
249	            const scale = Math.min(1.25, 0.86 / Math.max(width / fullWidth, height / fullHeight));
250	            const translate = [fullWidth / 2 - scale * (bounds.x + width / 2), fullHeight / 2 - scale * (bounds.y + height / 2)];
251	            svgSelection.transition().duration(300).call(zoomBehavior.transform, window.d3.zoomIdentity.translate(translate[0], translate[1]).scale(scale));
252	          }}
253	          function focusNode(node) {{
254	            if (!node || !svgSelection || !zoomBehavior) return;
255	            const svg = svgSelection.node();
256	            const scale = Math.max(0.85, window.d3.zoomTransform(svg).k || 1);
257	            const translate = [(svg.clientWidth || 1000) / 2 - node.x * scale, (svg.clientHeight || 700) / 2 - node.y * scale];
258	            svgSelection.transition().duration(260).call(zoomBehavior.transform, window.d3.zoomIdentity.translate(translate[0], translate[1]).scale(scale));
259	          }}
260	          function resetZoom() {{ if (svgSelection && zoomBehavior) svgSelection.transition().duration(220).call(zoomBehavior.transform, window.d3.zoomIdentity); }}
261	          function zoomBy(factor) {{ if (svgSelection && zoomBehavior) svgSelection.transition().duration(140).call(zoomBehavior.scaleBy, factor); }}
262	
263	          function selectTourStep(index, options = {{}}) {{
264	            const graph = activeGraph();
265	            const tour = graph.tour || [];
266	            if (!tour.length) return;
267	            tourIndex = Math.max(0, Math.min(index, tour.length - 1));
268	            const nodes = nodeMap(graph);
269	            const node = nodes.get(tour[tourIndex].nodeId) || (graph.nodes || [])[0];
270	            selectedNodeId = node?.id || null;
271	            renderTour(graph);
272	            renderDetails(node, graph);
273	            applyFilters(graph);
274	            if (!options.noFocus) focusNode(node);
275	          }}
276	          function nextTourStep() {{ selectTourStep(tourIndex + 1); }}
277	          function previousTourStep() {{ selectTourStep(tourIndex - 1); }}
278	          function restartTour() {{ selectTourStep(0); }}
279	
280	          function renderActiveGraph(options = {{}}) {{
281	            const graph = activeGraph();
282	            if (!graph) throw new Error('No active graph');
283	            const svg = window.d3.select('#pr-walkthrough-canvas');
284	            if (svg.empty()) throw new Error('Missing #pr-walkthrough-canvas');
285	            svg.selectAll('*').remove();
286	            svgSelection = svg;
287	            const nodesById = nodeMap(graph);
288	            const defs = svg.append('defs');
289	            defs.append('marker').attr('id', `d3-arrowhead-${{graph.id}}`).attr('class', 'd3-edge-arrow').attr('viewBox', '0 -6 12 12').attr('refX', 11).attr('refY', 0).attr('markerWidth', 9).attr('markerHeight', 9).attr('orient', 'auto').attr('markerUnits', 'strokeWidth').style('--edge-color', graph.color || '#868584').append('path').attr('d', 'M0,-6L12,0L0,6Z');
290	            const root = svg.append('g').attr('class', 'd3-zoom-root');
291	            viewportSelection = root.append('g').attr('class', 'd3-viewport');
292	            viewportSelection.append('text').attr('class', 'd3-graph-title').attr('x', -420).attr('y', -300).attr('fill', graph.color || '#a43787').text(graph.label || graph.id);
293	            const edgeLayer = viewportSelection.append('g').attr('class', 'd3-edges');
294	            const nodeLayer = viewportSelection.append('g').attr('class', 'd3-nodes');
295	            const edges = edgeLayer.selectAll('.d3-edge').data(graph.edges || []).join('g').attr('class', 'd3-edge').attr('data-edge-id', (edge, index) => edge.id || `${{edge.source}}-${{edge.target}}-${{index}}`).style('--edge-color', graph.color || '#868584');
296	            edges.append('path').attr('d', (edge) => pathForEdge(edge, nodesById, graph)).attr('marker-end', `url(#d3-arrowhead-${{graph.id}})`);
297	            edges.append('text').append('textPath').attr('href', function href(_, index) {{ const path = window.d3.select(edges.nodes()[index]).select('path'); const id = `d3-edge-path-${{graph.id}}-${{index}}`; path.attr('id', id); return `#${{id}}`; }}).attr('startOffset', '50%').attr('text-anchor', 'middle').text((edge) => edge.label || '');
298	            const nodes = nodeLayer.selectAll('.d3-node').data(graph.nodes || []).join('g').attr('class', (node) => `d3-node${{graph.id === 'system-overview' ? ' is-overview-card' : ''}}`).attr('data-node-id', (node) => node.id).attr('tabindex', 0).attr('role', 'button').attr('aria-label', (node) => node.title).attr('transform', (node) => `translate(${{node.x || 0}}, ${{node.y || 0}})`).style('--node-color', graph.color || '#a43787').on('click keydown', (event, node) => {{
299	              if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
300	              selectedNodeId = node.id;
301	              const tourPosition = (graph.tour || []).findIndex((step) => step.nodeId === node.id);
302	              if (tourPosition >= 0) tourIndex = tourPosition;
303	              renderTour(graph);
304	              renderDetails(node, graph);
