function quizQuestions() {{
  return Array.isArray(currentData.quiz) ? currentData.quiz : [];
}}
function hashString(value) {{
  let hash = 5381;
  const text = String(value);
  for (let i = 0; i < text.length; i += 1) hash = ((hash * 33) ^ text.charCodeAt(i)) >>> 0;
  return hash;
}}
function deterministicOrder(options, seed) {{
  // Stable shuffle keyed by the question so option positions never leak the answer,
  // yet stay identical across reloads (no Math.random, matching the deterministic render).
  return (options || [])
    .map((option, index) => ({{ index, sort: hashString(`${{seed}}:${{index}}:${{option}}`) }}))
    .sort((a, b) => a.sort - b.sort)
    .map((entry) => entry.index);
}}
function updateQuizScore() {{
  const total = quizQuestions().length;
  const answered = document.querySelectorAll('.d3-quiz-q.is-answered').length;
  const correct = document.querySelectorAll('.d3-quiz-q.is-correct-answer').length;
  const score = document.querySelector('.d3-quiz-score');
  if (score) score.textContent = `Score ${{correct}} / ${{total}} correct · ${{answered}} / ${{total}} answered`;
}}
function renderQuiz() {{
  const container = document.getElementById('pr-walkthrough-quiz-body');
  if (!container) return;
  const questions = quizQuestions();
  if (!questions.length) {{
    container.innerHTML = '<p class="d3-quiz-empty">No comprehension quiz was included for this PR.</p>';
    return;
  }}
  container.innerHTML = `
    <p class="d3-quiz-score" role="status" aria-live="polite">Score 0 / ${{questions.length}} correct · 0 / ${{questions.length}} answered</p>
    ${{questions.map((question, qIndex) => {{
      const order = deterministicOrder(question.options, `${{qIndex}}:${{question.question || ''}}`);
      const options = order.map((optionIndex) => {{
        const isCorrect = optionIndex === Number(question.answerIndex);
        return `<button type="button" class="d3-quiz-option" data-correct="${{isCorrect ? 'true' : 'false'}}">${{escapeHtml((question.options || [])[optionIndex])}}</button>`;
      }}).join('');
      return `
        <section class="d3-quiz-q" data-quiz-index="${{qIndex}}">
          <span class="d3-quiz-q-index">Question ${{qIndex + 1}} / ${{questions.length}}</span>
          <p class="d3-quiz-q-prompt">${{escapeHtml(question.question || '')}}</p>
          <div class="d3-quiz-options">${{options}}</div>
          <p class="d3-quiz-explanation">${{escapeHtml(question.explanation || '')}}</p>
        </section>`;
    }}).join('')}}
  `;
  container.querySelectorAll('.d3-quiz-q').forEach((questionEl) => {{
    questionEl.querySelectorAll('.d3-quiz-option').forEach((button) => {{
      button.addEventListener('click', () => {{
        if (questionEl.classList.contains('is-answered')) return;
        questionEl.classList.add('is-answered');
        if (button.dataset.correct === 'true') questionEl.classList.add('is-correct-answer');
        questionEl.querySelectorAll('.d3-quiz-option').forEach((optionButton) => {{
          optionButton.disabled = true;
          if (optionButton.dataset.correct === 'true') optionButton.classList.add('is-correct');
          else if (optionButton === button) optionButton.classList.add('is-incorrect');
        }});
        updateQuizScore();
      }});
    }});
  }});
}}
