#!/usr/bin/env python3
"""Render a self-contained, reading-first PR walkthrough page.

No D3, no canvas, no CDN, no network. The page is one calm scrollable
column (Apple Books style): a lead, a few distinct-purpose sections, and
an optional comprehension quiz. The only JavaScript is the quiz, and it is
inline and dependency-free.

Data model ({meta, sections, quiz}):
  meta:     {title, prUrl, baseRef, headRef, summary}
  sections: [{kicker, title, intro, entries[], flow[]}]
              entry: {label, title, body, details[], files[{path,url}]}
              flow:  {from, to, note}   (optional; a plain, upright data path)
  quiz:     [{question, options[], answerIndex, explanation}]
"""
from __future__ import annotations

import argparse
import html
import json
from pathlib import Path
from textwrap import dedent


def reading_css() -> str:
    return dedent(
        """
        :root {
          color-scheme: light dark;
          --pw-bg: #f7f2e9;
          --pw-surface: #fffdf8;
          --pw-ink: #22201c;
          --pw-muted: #6b665d;
          --pw-faint: #8f897e;
          --pw-rule: #e4ddcf;
          --pw-accent: #9a2f7f;
          --pw-good: #2f7d54;
          --pw-code-bg: #efe8da;
          --pw-measure: 42rem;
          --pw-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", system-ui, sans-serif;
          --pw-mono: "SF Mono", "Roboto Mono", ui-monospace, Menlo, monospace;
        }
        @media (prefers-color-scheme: dark) {
          :root {
            --pw-bg: #1a1917;
            --pw-surface: #201f1c;
            --pw-ink: #e9e5dc;
            --pw-muted: #a8a297;
            --pw-faint: #7d786e;
            --pw-rule: #322f2a;
            --pw-accent: #d789bf;
            --pw-good: #6cc08c;
            --pw-code-bg: #2a2824;
          }
        }
        * { box-sizing: border-box; }
        html { -webkit-text-size-adjust: 100%; }
        body {
          margin: 0;
          background: var(--pw-bg);
          color: var(--pw-ink);
          font-family: var(--pw-sans);
          font-size: 1.125rem;
          line-height: 1.65;
          -webkit-font-smoothing: antialiased;
          text-rendering: optimizeLegibility;
        }
        .pw {
          max-width: var(--pw-measure);
          margin: 0 auto;
          padding: clamp(2.5rem, 6vw, 5rem) 1.375rem 6rem;
        }
        a { color: var(--pw-accent); text-underline-offset: 2px; }
        .pw-kicker {
          margin: 0 0 1.1rem;
          color: var(--pw-accent);
          font-family: var(--pw-mono);
          font-size: 0.75rem;
          letter-spacing: 0.14em;
          text-transform: uppercase;
        }
        .pw-title {
          margin: 0;
          font-size: clamp(2rem, 5.5vw, 3.1rem);
          line-height: 1.05;
          letter-spacing: -0.021em;
          font-weight: 700;
        }
        .pw-meta {
          margin: 1.1rem 0 0;
          color: var(--pw-muted);
          font-family: var(--pw-mono);
          font-size: 0.82rem;
        }
        .pw-lead {
          margin: 1.6rem 0 0;
          font-size: 1.28rem;
          line-height: 1.5;
          color: var(--pw-ink);
        }
        .pw-toc {
          margin: 2.6rem 0 0;
          padding: 0.2rem 0 0;
          display: flex;
          flex-wrap: wrap;
          gap: 0.4rem 1.1rem;
          border-top: 1px solid var(--pw-rule);
          padding-top: 1.1rem;
        }
        .pw-toc a {
          color: var(--pw-muted);
          text-decoration: none;
          font-size: 0.9rem;
        }
        .pw-toc a:hover { color: var(--pw-accent); }
        .pw-section { margin-top: clamp(3.2rem, 7vw, 4.6rem); }
        .pw-section-kicker {
          margin: 0 0 0.5rem;
          color: var(--pw-accent);
          font-family: var(--pw-mono);
          font-size: 0.72rem;
          letter-spacing: 0.14em;
          text-transform: uppercase;
        }
        .pw-section-title {
          margin: 0;
          font-size: clamp(1.5rem, 3.4vw, 1.95rem);
          line-height: 1.12;
          letter-spacing: -0.014em;
          font-weight: 650;
        }
        .pw-section-intro {
          margin: 0.9rem 0 0;
          color: var(--pw-muted);
          font-size: 1.09rem;
          line-height: 1.6;
        }
        .pw-flow {
          margin: 1.7rem 0 0;
          padding: 1rem 1.1rem;
          background: var(--pw-code-bg);
          border-radius: 12px;
          font-family: var(--pw-mono);
          font-size: 0.86rem;
          line-height: 1.5;
          overflow-x: auto;
        }
        .pw-flow-row { display: block; white-space: nowrap; }
        .pw-flow-arrow { color: var(--pw-accent); padding: 0 0.5ch; }
        .pw-flow-note { color: var(--pw-faint); padding-left: 1.5ch; }
        .pw-entry { margin-top: 2.1rem; padding-left: 1.1rem; border-left: 2px solid var(--pw-rule); }
        .pw-entry-label {
          margin: 0 0 0.3rem;
          color: var(--pw-faint);
          font-family: var(--pw-mono);
          font-size: 0.7rem;
          letter-spacing: 0.1em;
          text-transform: uppercase;
        }
        .pw-entry-title { margin: 0; font-size: 1.2rem; line-height: 1.25; font-weight: 640; }
        .pw-entry-body { margin: 0.55rem 0 0; }
        .pw-entry-details { margin: 0.7rem 0 0; padding-left: 1.1rem; color: var(--pw-muted); font-size: 1rem; }
        .pw-entry-details li { margin: 0.25rem 0; }
        .pw-entry-files { margin: 0.7rem 0 0; font-family: var(--pw-mono); font-size: 0.8rem; }
        .pw-entry-files a { display: inline-block; margin-right: 1rem; overflow-wrap: anywhere; }
        code, .pw-code { font-family: var(--pw-mono); font-size: 0.9em; background: var(--pw-code-bg); padding: 0.1em 0.35em; border-radius: 5px; }

        .pw-quiz { margin-top: clamp(3.6rem, 8vw, 5rem); border-top: 1px solid var(--pw-rule); padding-top: clamp(2.4rem, 5vw, 3.2rem); }
        .pw-quiz-intro { margin: 0.9rem 0 0; color: var(--pw-muted); }
        .pw-quiz-score { margin: 1.4rem 0 0; color: var(--pw-accent); font-family: var(--pw-mono); font-size: 0.82rem; letter-spacing: 0.04em; }
        .pw-q { margin-top: 2rem; }
        .pw-q-index { color: var(--pw-faint); font-family: var(--pw-mono); font-size: 0.7rem; letter-spacing: 0.1em; text-transform: uppercase; }
        .pw-q-prompt { margin: 0.4rem 0 0.9rem; font-size: 1.15rem; line-height: 1.35; font-weight: 600; }
        .pw-options { display: grid; gap: 0.55rem; }
        .pw-option {
          text-align: left;
          font: inherit;
          color: var(--pw-ink);
          background: var(--pw-surface);
          border: 1px solid var(--pw-rule);
          border-radius: 12px;
          padding: 0.8rem 1rem;
          cursor: pointer;
          line-height: 1.4;
          transition: border-color 120ms ease, background 120ms ease;
        }
        .pw-option:hover:not(:disabled) { border-color: var(--pw-accent); }
        .pw-option:disabled { cursor: default; }
        .pw-option.is-correct { border-color: var(--pw-good); background: color-mix(in srgb, var(--pw-good) 12%, var(--pw-surface)); }
        .pw-option.is-incorrect { border-color: var(--pw-accent); opacity: 0.75; }
        .pw-explanation { display: none; margin: 0.8rem 0 0; padding-left: 1rem; border-left: 2px solid var(--pw-rule); color: var(--pw-muted); line-height: 1.55; }
        .pw-q.is-answered .pw-explanation { display: block; }
        .pw-quiz-empty { color: var(--pw-faint); }

        .pw-foot { margin-top: 4rem; padding-top: 1.4rem; border-top: 1px solid var(--pw-rule); color: var(--pw-faint); font-family: var(--pw-mono); font-size: 0.76rem; line-height: 1.6; }
        @media (prefers-reduced-motion: reduce) { .pw-option { transition: none; } }
        """
    ).strip()


def quiz_script() -> str:
    return dedent(
        """
        <script>
        (() => {
          const data = (() => {
            const tag = document.getElementById('pw-data');
            if (!tag) return {};
            try { return JSON.parse(tag.textContent || '{}'); } catch (e) { return {}; }
          })();
          const questions = Array.isArray(data.quiz) ? data.quiz : [];
          const body = document.getElementById('pw-quiz-body');
          if (!body) return;
          if (!questions.length) { body.innerHTML = '<p class="pw-quiz-empty">No comprehension quiz was included for this PR.</p>'; return; }

          const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
          // Stable, seed-based shuffle so option positions never leak the answer
          // yet stay identical across reloads (no Math.random).
          const hash = (s) => { let h = 5381; s = String(s); for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h; };
          const order = (opts, seed) => opts.map((o, i) => ({ i, k: hash(seed + ':' + i + ':' + o) })).sort((a, b) => a.k - b.k).map((e) => e.i);

          const total = questions.length;
          const updateScore = () => {
            const answered = document.querySelectorAll('.pw-q.is-answered').length;
            const correct = document.querySelectorAll('.pw-q.is-correct-answer').length;
            const el = document.querySelector('.pw-quiz-score');
            if (el) el.textContent = 'Score ' + correct + ' / ' + total + ' correct | ' + answered + ' / ' + total + ' answered';
          };

          body.innerHTML =
            '<p class="pw-quiz-score" role="status" aria-live="polite">Score 0 / ' + total + ' correct | 0 / ' + total + ' answered</p>' +
            questions.map((q, qi) => {
              const opts = order(q.options || [], qi + ':' + (q.question || '')).map((oi) => {
                const correct = oi === Number(q.answerIndex);
                return '<button type="button" class="pw-option" data-correct="' + (correct ? 'true' : 'false') + '">' + esc((q.options || [])[oi]) + '</button>';
              }).join('');
              return '<section class="pw-q" data-q="' + qi + '">' +
                '<span class="pw-q-index">Question ' + (qi + 1) + ' / ' + total + '</span>' +
                '<p class="pw-q-prompt">' + esc(q.question || '') + '</p>' +
                '<div class="pw-options">' + opts + '</div>' +
                '<p class="pw-explanation">' + esc(q.explanation || '') + '</p>' +
                '</section>';
            }).join('');

          body.querySelectorAll('.pw-q').forEach((qEl) => {
            qEl.querySelectorAll('.pw-option').forEach((btn) => {
              btn.addEventListener('click', () => {
                if (qEl.classList.contains('is-answered')) return;
                qEl.classList.add('is-answered');
                if (btn.dataset.correct === 'true') qEl.classList.add('is-correct-answer');
                qEl.querySelectorAll('.pw-option').forEach((b) => {
                  b.disabled = true;
                  if (b.dataset.correct === 'true') b.classList.add('is-correct');
                  else if (b === btn) b.classList.add('is-incorrect');
                });
                updateScore();
              });
            });
          });
        })();
        </script>
        """
    ).strip()


def _files_markup(files: list) -> str:
    if not files:
        return ""
    links = "".join(
        f'<a href="{html.escape(str(f.get("url") or "#"))}" target="_blank" rel="noreferrer">{html.escape(str(f.get("path") or f.get("label") or "file"))}</a>'
        for f in files
    )
    return f'<p class="pw-entry-files">{links}</p>'


def _details_markup(details: list) -> str:
    if not details:
        return ""
    items = "".join(f"<li>{html.escape(str(d))}</li>" for d in details)
    return f'<ul class="pw-entry-details">{items}</ul>'


def _entry_markup(entry: dict) -> str:
    label = entry.get("label")
    label_html = f'<p class="pw-entry-label">{html.escape(str(label))}</p>' if label else ""
    return (
        '<div class="pw-entry">'
        f"{label_html}"
        f'<h3 class="pw-entry-title">{html.escape(str(entry.get("title") or ""))}</h3>'
        f'<p class="pw-entry-body">{html.escape(str(entry.get("body") or ""))}</p>'
        f"{_details_markup(entry.get('details') or [])}"
        f"{_files_markup(entry.get('files') or [])}"
        "</div>"
    )


def _flow_markup(flow: list) -> str:
    if not flow:
        return ""
    rows = ""
    for step in flow:
        note = step.get("note")
        note_html = f'<span class="pw-flow-note">{html.escape(str(note))}</span>' if note else ""
        rows += (
            '<span class="pw-flow-row">'
            f'{html.escape(str(step.get("from") or ""))}'
            '<span class="pw-flow-arrow">-&gt;</span>'
            f'{html.escape(str(step.get("to") or ""))}'
            f"{note_html}"
            "</span>"
        )
    return f'<div class="pw-flow">{rows}</div>'


def _section_markup(section: dict, index: int) -> str:
    kicker = section.get("kicker")
    kicker_html = f'<p class="pw-section-kicker">{html.escape(str(kicker))}</p>' if kicker else ""
    intro = section.get("intro")
    intro_html = f'<p class="pw-section-intro">{html.escape(str(intro))}</p>' if intro else ""
    entries = "".join(_entry_markup(e) for e in (section.get("entries") or []))
    return (
        f'<section class="pw-section" id="section-{index}">'
        f"{kicker_html}"
        f'<h2 class="pw-section-title">{html.escape(str(section.get("title") or ""))}</h2>'
        f"{intro_html}"
        f"{_flow_markup(section.get('flow') or [])}"
        f"{entries}"
        "</section>"
    )


def _toc_markup(sections: list, has_quiz: bool) -> str:
    links = "".join(
        f'<a href="#section-{i}">{html.escape(str(s.get("title") or f"Section {i + 1}"))}</a>'
        for i, s in enumerate(sections)
    )
    if has_quiz:
        links += '<a href="#quiz">Quiz</a>'
    return f'<nav class="pw-toc" aria-label="Contents">{links}</nav>'


def html_template(data: dict) -> str:
    meta = data.get("meta") or {}
    title = str(meta.get("title") or "PR walkthrough")
    summary = str(meta.get("summary") or "")
    pr_url = str(meta.get("prUrl") or "")
    base = str(meta.get("baseRef") or "")
    head = str(meta.get("headRef") or "")
    sections = data.get("sections") or []
    quiz = data.get("quiz") or []

    meta_bits = []
    if base or head:
        meta_bits.append(f"{html.escape(base)} &lt;- {html.escape(head)}")
    if pr_url:
        meta_bits.append(f'<a href="{html.escape(pr_url)}" target="_blank" rel="noreferrer">Open PR</a>')
    meta_html = f'<p class="pw-meta">{" -- ".join(meta_bits)}</p>' if meta_bits else ""
    lead_html = f'<p class="pw-lead">{html.escape(summary)}</p>' if summary else ""
    toc_html = _toc_markup(sections, bool(quiz)) if sections else ""
    sections_html = "".join(_section_markup(s, i) for i, s in enumerate(sections))

    quiz_html = ""
    if quiz:
        quiz_html = (
            '<section class="pw-quiz" id="quiz">'
            '<p class="pw-section-kicker">Check yourself</p>'
            '<h2 class="pw-section-title">Comprehension quiz</h2>'
            '<p class="pw-quiz-intro">Pick an answer to see whether it is right and why.</p>'
            '<div id="pw-quiz-body"></div>'
            "</section>"
        )

    data_json = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    return dedent(
        f"""
        <!doctype html>
        <html lang="en">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>{html.escape(title)}</title>
          <style>{reading_css()}</style>
        </head>
        <body>
          <article class="pw">
            <header class="pw-head">
              <p class="pw-kicker">PR walkthrough</p>
              <h1 class="pw-title">{html.escape(title)}</h1>
              {meta_html}
              {lead_html}
            </header>
            {toc_html}
            {sections_html}
            {quiz_html}
            <footer class="pw-foot">Orientation only -- read the diff for the full change. Not a code review.</footer>
          </article>
          <script id="pw-data" type="application/json">{data_json}</script>
          {quiz_script()}
        </body>
        </html>
        """
    ).strip()


def sample_data() -> dict:
    return {
        "meta": {
            "title": "Sample reading walkthrough",
            "prUrl": "",
            "baseRef": "main",
            "headRef": "feature",
            "summary": "Replace this with the one-paragraph why of the PR: what it changes and why it matters.",
        },
        "sections": [
            {
                "kicker": "Orientation",
                "title": "The subsystem this touches",
                "intro": "A few stable facts a reviewer needs before reading the change. Keep this PR-agnostic.",
                "entries": [
                    {"label": "data model", "title": "The core record", "body": "Define the main table or state owner and what it is the source of truth for.", "details": ["One extra fact if it helps orientation."]},
                    {"label": "surface", "title": "Where the user acts", "body": "Name the component or entry point the user interacts with.", "files": []},
                ],
            },
            {
                "kicker": "The change",
                "title": "What this PR actually does",
                "intro": "Tell the story once, in a sensible order. Do not repeat it from a second angle.",
                "flow": [
                    {"from": "input", "to": "transform()", "note": "what happens"},
                    {"from": "transform()", "to": "stored/result", "note": "and then"},
                ],
                "entries": [
