#!/usr/bin/env python3
"""Statically validate a reading-first PR walkthrough HTML page.

Checks structure and content only -- it does not run a browser. Open the
file:// URL to confirm it reads well. Self-contained by design: the page
must load with no network at all.
"""
from __future__ import annotations

import argparse
import html as html_mod
import json
import re
from html.parser import HTMLParser
from pathlib import Path


class DataExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.capture = False
        self.parts: list[str] = []

    def handle_starttag(self, tag, attrs):
        if tag == "script" and dict(attrs).get("id") == "pw-data":
            self.capture = True
            self.parts = []

    def handle_endtag(self, tag):
        if tag == "script":
            self.capture = False

    def handle_data(self, data):
        if self.capture:
            self.parts.append(data)


def extract_data(html_text: str) -> dict:
    parser = DataExtractor()
    parser.feed(html_text)
    if parser.parts:
        raw = "".join(parser.parts)
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return json.loads(html_mod.unescape(raw))
    raise ValueError("Missing inline #pw-data JSON block")


def static_validate(html_text: str, data: dict) -> list[str]:
    errors: list[str] = []

    if "fetch(" in html_text:
        errors.append("HTML uses fetch(); the page must be fully inline for file:// use")
    if re.search(r"<script[^>]+\bsrc=", html_text):
        errors.append("HTML loads an external script; the page must have no network dependencies")
    if re.search(r'<link[^>]+rel=["\']?stylesheet', html_text):
        errors.append("HTML links an external stylesheet; inline the CSS instead")
    if re.search(r'https?://cdn', html_text):
        errors.append("HTML references a CDN; the reading page must not depend on one")
    if 'class="pw"' not in html_text:
        errors.append("Missing the .pw reading container")

    meta = data.get("meta") or {}
    if not meta.get("title"):
        errors.append("meta.title is empty")

    sections = data.get("sections") or []
    if not sections:
        errors.append("No sections: a reading walkthrough needs at least one section")
    for si, section in enumerate(sections):
        where = f"section {si + 1}"
        if not section.get("title"):
            errors.append(f"{where} missing title")
        entries = section.get("entries") or []
        flow = section.get("flow") or []
        if not entries and not flow:
            errors.append(f"{where} has neither entries nor a flow -- it would render empty")
        for ei, entry in enumerate(entries):
            if not entry.get("title"):
                errors.append(f"{where} entry {ei + 1} missing title")
            if not entry.get("body"):
                errors.append(f"{where} entry {ei + 1} ({entry.get('title')}) missing body text")
        for fi, step in enumerate(flow):
            if not step.get("from") or not step.get("to"):
                errors.append(f"{where} flow step {fi + 1} needs both 'from' and 'to'")

    quiz = data.get("quiz") or []
    if not quiz:
        errors.append("Missing comprehension quiz: add a non-empty 'quiz' array (2-5 questions, scaled to PR size)")
    if quiz and 'id="pw-quiz-body"' not in html_text:
        errors.append("Quiz data present but the page has no #pw-quiz-body mount")
    for qi, q in enumerate(quiz):
        options = q.get("options") or []
        if not q.get("question"):
            errors.append(f"Quiz question {qi + 1} missing prompt text")
        if len(options) < 2:
            errors.append(f"Quiz question {qi + 1} needs at least 2 options")
        answer_index = q.get("answerIndex")
        # bool is a subclass of int, so reject it explicitly
        if not isinstance(answer_index, int) or isinstance(answer_index, bool) or not (0 <= answer_index < len(options)):
            errors.append(f"Quiz question {qi + 1} has an invalid answerIndex (must be an in-range integer)")
        if not q.get("explanation"):
            errors.append(f"Quiz question {qi + 1} missing explanation")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description="Statically validate a reading-first PR walkthrough page.")
    parser.add_argument("--html", required=True, type=Path, help="Path to pr-walkthrough/index.html")
    args = parser.parse_args()

    html_text = args.html.read_text()
    data = extract_data(html_text)
    errors = static_validate(html_text, data)
    if errors:
        for error in errors:
            print(f"FAIL - {error}")
        return 1
    section_count = len(data.get("sections") or [])
    entry_count = sum(len(s.get("entries") or []) for s in data.get("sections") or [])
    quiz_count = len(data.get("quiz") or [])
    print(f"PASS - static validation passed: {section_count} section(s), {entry_count} entry/entries, {quiz_count} quiz question(s).")
    print("note: static checks only. Open the printed file:// URL and read it to confirm it flows well.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

